create or replace function public.project_funnel_event(p_event_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$ declare e public.integration_events%rowtype; p jsonb; a jsonb; v_session text; v_checkout uuid; v_tx uuid; v_sale text; begin select * into e from public.integration_events where id=p_event_id for update; if not found then return jsonb_build_object('ok',false,'error','event_not_found'); end if; p=coalesce(e.payload,'{}'::jsonb); if e.event_type='page_view' then v_session=coalesce(nullif(p->>'session_key',''),nullif(p->>'session_id','')); if v_session is not null then insert into public.attribution_sessions(user_id,funnel_id,session_key,source,medium,campaign,content,term,click_id,landing_url,first_seen_at,last_seen_at,metadata) values(e.user_id,e.funnel_id,v_session,p->>'source',p->>'medium',p->>'campaign',p->>'content',p->>'term',p->>'click_id',p->>'landing_url',coalesce(e.occurred_at,now()),coalesce(e.occurred_at,now()),coalesce(p->'metadata','{}'::jsonb)) on conflict do nothing; end if; elsif e.event_type in ('checkout_started','checkout_abandoned') then if nullif(p->>'checkout_id','') is not null then v_checkout=(p->>'checkout_id')::uuid; update public.checkout_sessions set status=case when e.event_type='checkout_abandoned' then 'abandoned' else 'pending' end, abandoned_at=case when e.event_type='checkout_abandoned' then coalesce(abandoned_at,e.occurred_at,now()) else abandoned_at end, updated_at=now() where id=v_checkout and user_id=e.user_id; end if; elsif e.event_type in ('purchase','upsell') then if nullif(p->>'transaction_id','') is not null then v_tx=(p->>'transaction_id')::uuid; update public.gateway_transactions set status='approved',completed_at=coalesce(completed_at,e.occurred_at,now()),updated_at=now() where id=v_tx and user_id=e.user_id; end if; v_sale=coalesce(nullif(p->>'sale_id',''),nullif(p->>'external_id',''),e.external_id,'sale_'||e.id::text); insert into public.sales(id,user_id,funnel_id,product_id,checkout_id,transaction_id,amount,currency,status,attribution,source,medium,campaign,content,term,click_id,external_id,gateway_id,occurred_at,data) values(v_sale,e.user_id,e.funnel_id,nullif(p->>'product_id',''),v_checkout,v_tx,coalesce((p->>'amount')::numeric,0),coalesce(nullif(p->>'currency',''),'BRL'),'approved',coalesce(p->'attribution','{}'::jsonb),p->>'source',p->>'medium',p->>'campaign',p->>'content',p->>'term',p->>'click_id',e.external_id,p->>'gateway_id',coalesce(e.occurred_at,now()),p) on conflict (id) do update set status='approved',amount=excluded.amount,transaction_id=coalesce(excluded.transaction_id,sales.transaction_id),checkout_id=coalesce(excluded.checkout_id,sales.checkout_id),occurred_at=excluded.occurred_at,data=excluded.data; elsif e.event_type in ('refund','chargeback') then if nullif(p->>'transaction_id','') is not null then v_tx=(p->>'transaction_id')::uuid; update public.gateway_transactions set status=case when e.event_type='chargeback' then 'chargeback' else 'refunded' end,updated_at=now() where id=v_tx and user_id=e.user_id; update public.sales set status=case when e.event_type='chargeback' then 'chargeback' else 'refunded' end where transaction_id=v_tx and user_id=e.user_id; elsif e.external_id is not null then update public.sales set status=case when e.event_type='chargeback' then 'chargeback' else 'refunded' end where external_id=e.external_id and user_id=e.user_id; end if; end if; return jsonb_build_object('ok',true,'event_id',e.id,'event_type',e.event_type); exception when others then return jsonb_build_object('ok',false,'error',sqlerrm); end; $$; revoke execute on function public.project_funnel_event(uuid) from public,anon,authenticated; grant execute on function public.project_funnel_event(uuid) to service_role;